pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        address baseToken = address(0x1);
        address nft = address(0x2);
        uint128 virtualBaseTokenReserves = 1000;
        uint128 virtualNftReserves = 1000;
        uint56 changeFee = 12345;
        uint16 feeRate = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolenNftOracle = false;
        bool payRoyalties = false;

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        assertTrue(c.changeFee() == 12345, "changeFee should be 12345");
    }
}
